<?php declare(strict_types=1); $catalogBase = ($currentUser['tipo'] ?? null)==='superadmin' ? '/superadmin/catalogos' : '/catalogos'; ?>
<div data-feedback hidden></div><div class="row g-4"><div class="col-lg-4"><div class="card"><div class="card-header"><h2 class="card-title">Nuevo catálogo</h2></div><div class="card-body"><form action="<?= e($catalogBase) ?>" method="post" data-ajax-form><div class="mb-2"><label class="form-label">Código</label><input class="form-control" name="codigo" required></div><div class="mb-2"><label class="form-label">Nombre</label><input class="form-control" name="nombre" required></div><div class="mb-3"><label class="form-label">Alcance</label><select class="form-select" name="alcance"><?php if(($currentUser['tipo']??null)==='superadmin'): ?><option value="global">Global</option><?php else: ?><option value="firma">Firma</option><?php endif; ?></select></div><button class="btn btn-primary">Crear catálogo</button></form></div></div></div>
<div class="col-lg-8"><div class="card"><div class="card-header"><h2 class="card-title">Catálogos disponibles</h2></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Catálogo</th><th>Alcance</th><th>Ítems</th></tr></thead><tbody><?php foreach($catalogos as $catalogo): ?><tr><td><strong><?= e($catalogo['nombre']) ?></strong><div><code><?= e($catalogo['codigo']) ?></code></div></td><td><?= e($catalogo['alcance']) ?></td><td><?= (int) $catalogo['items'] ?><details><summary class="small">Añadir ítem</summary><form class="mt-2" action="<?= e($catalogBase) ?>/<?= (int) $catalogo['id'] ?>/items" method="post" data-ajax-form><input class="form-control form-control-sm mb-1" name="codigo" placeholder="Código"><input class="form-control form-control-sm mb-1" name="etiqueta" placeholder="Etiqueta"><input class="form-control form-control-sm mb-1" type="number" name="orden" value="0"><button class="btn btn-sm btn-primary">Añadir</button></form></details></td></tr><?php endforeach; ?><?php if($catalogos===[]): ?><tr><td colspan="3" class="text-center text-secondary py-4">No hay catálogos.</td></tr><?php endif; ?></tbody></table></div></div></div></div>
